# Worms Armageddon sprite palettes
# Extracted from Gfx0.dir and Gfx.dir at offset 24
# Each palette is 768 bytes (256 colors × 3 bytes RGB)

import struct

def get_palette(name: str) -> bytes:
    """Get a palette by name (e.g., 'gfx0', 'gfx', 'gfx1')"""
    if name in ('gfx', 'gfx1'):
        return _GFX_PALETTE
    return _GFX0_PALETTE

_GFX0_PALETTE = bytes.fromhex(
    ""
)

_GFX_PALETTE = bytes.fromhex(
    ""
)

PALETTES = {
    'gfx0': _GFX0_PALETTE,
    'gfx': _GFX_PALETTE,
    'gfx1': _GFX_PALETTE,
}
